    if (DD.ready('w11_bingoball')) ctx.drawImage(DD.IMG.w11_bingoball, X, Y - 6);   // the balls sit above the standing line
    else { ctx.fillStyle = '#e0e0ec'; ctx.fillRect(X, Y, e.w, e.h); }
