    ctx.fillStyle = on ? '#fff2a6' : '#f0c84a'; ctx.fillRect(X + 3, Y + 3, 6, 6); ctx.fillStyle = '#fff'; ctx.fillRect(X + 5, Y + 5, 2, 2);
