    for (let i = 0; i < 160; i++) { const x = ((i * 53 + 17) % 320), y = (i * 37) % 180; ctx.fillStyle = i % 3 ? '#c4b08a' : '#ece0c4'; ctx.fillRect(x, y, 2, 1); }
    const g = ctx.createLinearGradient(0, 0, 0, 180); g.addColorStop(0, 'rgba(40,30,10,0.32)'); g.addColorStop(0.4, 'rgba(255,240,200,0.05)'); g.addColorStop(1, 'rgba(0,0,0,0.1)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 320, 180);
